const CACHE='knowledge-campus-v3-1';
const CORE=['./','./index.html','./style.css?v=campus1','./app.js?v=campus1','./studio.js?v=campus1','./effects.js?v=campus1','./park.js?v=campus1','./learning-core.js','./simulations.js','./world-layout.js','./movement.js','./navigation.js','./movement.js?v=campus1','./navigation.js?v=campus1','./companion.js?v=campus1','./world-art.js?v=campus1','./discovery.js','./vendor/three.module.js','./content/science.json','./content/reasoning.json','./content/humanities.json'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('knowledge-campus-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy)).catch(()=>{});}return response;}).catch(async()=>{const cached=await caches.match(event.request);return cached||new Response('연결을 확인하고 다시 시도해 주세요.',{status:503});}));});
